'use client';

/**
 * @interlace/ui — DropdownMenu
 *
 * A button-triggered command menu — items, checkbox and radio items, submenus,
 * plus a `Compose` array shorthand. Wraps @base-ui/react/menu: Base UI owns
 * open state, positioning, focus and typeahead; we own the popup and the rows.
 *
 * The menu ARIA is upstream's too, except where this file steps out of it on
 * purpose — see below.
 *
 * ## Anatomy
 *
 *   DropdownMenu                     (Menu.Root — renders no DOM node)
 *     ├─ DropdownMenuTrigger         (Menu.Trigger)
 *     └─ DropdownMenuContent         (Portal → Positioner(z-50) → Popup — data-min-viewport=320)
 *          ├─ DropdownMenuLabel      (a plain div — see below)
 *          ├─ DropdownMenuGroup      (Menu.Group)
 *          ├─ DropdownMenuItem       (Menu.Item — variant default | destructive)
 *          ├─ DropdownMenuCheckboxItem / DropdownMenuRadioGroup + RadioItem
 *          ├─ DropdownMenuSeparator  (a plain div with role="separator")
 *          ├─ DropdownMenuShortcut   (span, ml-auto)
 *          └─ DropdownMenuSub        (SubmenuRoot → SubTrigger + SubContent)
 *
 * `DropdownMenuContent` is not a thin wrapper: it bundles Portal, Positioner
 * and Popup, so `side` / `align` / `sideOffset` are lifted onto it and any
 * other prop lands on the Popup.
 *
 * ## Where we deliberately left Base UI
 *
 *   - `DropdownMenuLabel` is a `<div>`, not `Menu.GroupLabel`. Base UI throws
 *     error #31 when a GroupLabel has no `Menu.Group` ancestor, and the
 *     canonical call site puts a heading straight inside the content. For a
 *     label that is semantically tied to a set of items, wrap them in
 *     `DropdownMenuGroup` and use Base UI's own GroupLabel inside it.
 *   - `DropdownMenuSeparator` is a `<div role="separator">` for the same
 *     reason of independence from menu structure.
 *
 * ## `Compose` — the array form
 *
 * `DropdownMenuCompose` (also reachable as `DropdownMenu.Compose`) renders
 * Root + Trigger + Content from `{ label, onSelect, shortcut, tone }` entries
 * plus `{ type: 'separator' | 'label' }`. Note it wires each entry's
 * `onSelect` to the item's `onClick`, not to Base UI's `onSelect`.
 *
 * ## MIN_VIEWPORT — 320
 *
 * The popup is `min-w-40` (160px) and capped by `max-h-(--available-height)`,
 * so it fits and scrolls at the 320 floor while Base UI's positioner shifts it
 * into view. Declared on the popup, because `Menu.Root` renders no DOM node.
 *
 * | Rule | Concept                          | Where in this file                                          |
 * | ---- | -------------------------------- | ----------------------------------------------------------- |
 * | R4   | Extends Base UI part props       | `React.ComponentProps<typeof BaseMenu.*>` on every wrapper  |
 * | R6   | data-slot per part               | dropdown-menu / -trigger / -content / -item / -sub-… (15)   |
 * | R7   | cn + ...rest                     | `cn('…', className)` + `{...props}` on every styled part    |
 * | R8   | Enum for item tone               | `variant = default | destructive` on `DropdownMenuItem`     |
 * | R10  | Composition seam                 | `Compose` for the array case; the parts for everything else |
 * | R12  | Reuse over wrap                  | Base UI owns open state, positioning, typeahead, roving focus |
 * | R14  | Declares min viewport            | `data-min-viewport` on the popup + exported const           |
 * | R19  | Tokens only                      | `bg-popover`, `bg-accent`, `text-destructive`, `ring-border` |
 * | R25  | Client component                 | Required — Base UI Menu ships client hooks                  |
 * | R26  | Keyboard contract                | Escape-dismissal asserted by `DropdownMenu.stories.tsx`, locked by `overlay-nav-keyboard-lock` |
 */

import * as React from 'react';

// @interlace/dropdown-menu v1.2.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/dropdown-menu
// What changed since: https://ds.interlace.tools/c/dropdown-menu#history
// Generated banner — keep it, the upgrade diff reads this version.

import { Menu as BaseMenu } from '@base-ui/react/menu';
import { CheckIcon, ChevronRightIcon, CircleIcon } from 'lucide-react';

import { cn } from '@/lib/utils';

/**
 * Minimum viable viewport (CSS px) — DESIGN_PRINCIPLES #14. The popup is
 * `min-w-40` (160px) and capped by `max-h-(--available-height)`, so it fits
 * and scrolls at the 320 floor; Base UI's positioner shifts it into view.
 * Projected onto the popup — `Menu.Root` renders no DOM node.
 */
export const MIN_VIEWPORT = 320 as const;

function DropdownMenu(props: React.ComponentProps<typeof BaseMenu.Root>) {
  return <BaseMenu.Root data-slot="dropdown-menu" {...props} />;
}

function DropdownMenuPortal(
  props: React.ComponentProps<typeof BaseMenu.Portal>,
) {
  return <BaseMenu.Portal data-slot="dropdown-menu-portal" {...props} />;
}

function DropdownMenuTrigger(
  props: React.ComponentProps<typeof BaseMenu.Trigger>,
) {
  return <BaseMenu.Trigger data-slot="dropdown-menu-trigger" {...props} />;
}

function DropdownMenuContent({
  className,
  side,
  sideOffset = 4,
  align = 'start',
  children,
  ...props
}: React.ComponentProps<typeof BaseMenu.Popup> & {
  side?: 'top' | 'right' | 'bottom' | 'left' | 'inline-start' | 'inline-end';
  sideOffset?: number;
  align?: 'start' | 'center' | 'end';
}) {
  return (
    <BaseMenu.Portal>
      <BaseMenu.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        className="z-50"
      >
        <BaseMenu.Popup
          data-slot="dropdown-menu-content"
          data-min-viewport={String(MIN_VIEWPORT)}
          className={cn(
            // `ring-border` (not `ring-black/5`): the raw black ring vanishes
            // on the dark surface, leaving the popup edgeless.
            'bg-popover text-popover-foreground border-border ring-border data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 max-h-(--available-height) min-w-40 origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-md border p-1 shadow-lg ring-1',
            className,
          )}
          {...props}
        >
          {children}
        </BaseMenu.Popup>
      </BaseMenu.Positioner>
    </BaseMenu.Portal>
  );
}

function DropdownMenuGroup(
  props: React.ComponentProps<typeof BaseMenu.Group>,
) {
  return <BaseMenu.Group data-slot="dropdown-menu-group" {...props} />;
}

function DropdownMenuItem({
  className,
  inset,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof BaseMenu.Item> & {
  inset?: boolean;
  variant?: 'default' | 'destructive';
}) {
  return (
    <BaseMenu.Item
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(
        "data-highlighted:bg-accent data-highlighted:text-accent-foreground focus:bg-accent focus:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:data-highlighted:bg-destructive/10 dark:data-[variant=destructive]:data-highlighted:bg-destructive/20 data-[variant=destructive]:data-highlighted:text-destructive data-[variant=destructive]:*:[svg]:text-destructive! [&_svg:not([class*='text-'])]:text-muted-foreground relative flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-disabled:pointer-events-none data-disabled:opacity-50 data-inset:pl-8 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 transition-colors",
        className,
      )}
      {...props}
    />
  );
}

function DropdownMenuCheckboxItem({
  className,
  children,
  checked,
  ...props
}: React.ComponentProps<typeof BaseMenu.CheckboxItem>) {
  return (
    <BaseMenu.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      className={cn(
        "data-highlighted:bg-accent data-highlighted:text-accent-foreground focus:bg-accent focus:text-accent-foreground relative flex cursor-default items-center gap-2 rounded-sm py-1.5 pr-2 pl-8 text-sm outline-hidden select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      checked={checked}
      {...props}
    >
      <span className="pointer-events-none absolute left-2 flex size-3.5 items-center justify-center">
        <BaseMenu.CheckboxItemIndicator>
          <CheckIcon className="size-4" />
        </BaseMenu.CheckboxItemIndicator>
      </span>
      {children}
    </BaseMenu.CheckboxItem>
  );
}

function DropdownMenuRadioGroup(
  props: React.ComponentProps<typeof BaseMenu.RadioGroup>,
) {
  return (
    <BaseMenu.RadioGroup data-slot="dropdown-menu-radio-group" {...props} />
  );
}

function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof BaseMenu.RadioItem>) {
  return (
    <BaseMenu.RadioItem
      data-slot="dropdown-menu-radio-item"
      className={cn(
        "data-highlighted:bg-accent data-highlighted:text-accent-foreground focus:bg-accent focus:text-accent-foreground relative flex cursor-default items-center gap-2 rounded-sm py-1.5 pr-2 pl-8 text-sm outline-hidden select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      {...props}
    >
      <span className="pointer-events-none absolute left-2 flex size-3.5 items-center justify-center">
        <BaseMenu.RadioItemIndicator>
          <CircleIcon className="size-2 fill-current" />
        </BaseMenu.RadioItemIndicator>
      </span>
      {children}
    </BaseMenu.RadioItem>
  );
}

// Standalone label (shadcn / radix semantics): a visual heading at the top
// of the menu, NOT a group label. Base UI's `Menu.GroupLabel` throws when
// rendered outside a `Menu.Group` ancestor — the canonical consumer pattern
// (`<DropdownMenuContent><DropdownMenuLabel>Sort by</DropdownMenuLabel>...`)
// doesn't wrap in a Group, so aliasing `DropdownMenuLabel` to GroupLabel
// surfaces error #31 on render. For semantic group labelling, wrap the
// items in `<DropdownMenuGroup>` and place a GroupLabel inside that group;
// callers that just want a visual heading get this plain div.
function DropdownMenuLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<'div'> & { inset?: boolean }) {
  return (
    <div
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(
        'px-2 py-1.5 text-sm font-medium data-[inset]:pl-8',
        className,
      )}
      {...props}
    />
  );
}

function DropdownMenuSeparator({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="dropdown-menu-separator"
      role="separator"
      className={cn('bg-border -mx-1 my-1 h-px', className)}
      {...props}
    />
  );
}

function DropdownMenuShortcut({
  className,
  ...props
}: React.ComponentProps<'span'>) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn(
        'text-muted-foreground ml-auto text-xs tracking-widest',
        className,
      )}
      {...props}
    />
  );
}

function DropdownMenuSub(
  props: React.ComponentProps<typeof BaseMenu.SubmenuRoot>,
) {
  return <BaseMenu.SubmenuRoot data-slot="dropdown-menu-sub" {...props} />;
}

function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: React.ComponentProps<typeof BaseMenu.SubmenuTrigger> & {
  inset?: boolean;
}) {
  return (
    <BaseMenu.SubmenuTrigger
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      className={cn(
        'data-highlighted:bg-accent data-highlighted:text-accent-foreground focus:bg-accent focus:text-accent-foreground data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground flex cursor-default items-center rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[inset]:pl-8',
        className,
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon className="ml-auto size-4" />
    </BaseMenu.SubmenuTrigger>
  );
}

function DropdownMenuSubContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof BaseMenu.Popup>) {
  return (
    <BaseMenu.Portal>
      <BaseMenu.Positioner>
        <BaseMenu.Popup
          data-slot="dropdown-menu-sub-content"
          className={cn(
            'bg-popover text-popover-foreground data-[open]:animate-in data-[closed]:animate-out data-[closed]:fade-out-0 data-[open]:fade-in-0 data-[closed]:zoom-out-95 data-[open]:zoom-in-95 z-50 min-w-[8rem] origin-(--transform-origin) overflow-hidden rounded-md border p-1 shadow-lg',
            className,
          )}
          {...props}
        >
          {children}
        </BaseMenu.Popup>
      </BaseMenu.Positioner>
    </BaseMenu.Portal>
  );
}

/* ─────────────────────────────────────────────────────────────────
 * DropdownMenuCompose — convenience composition.
 *
 * Renders Root + Trigger + Content with a single-prop API for the
 * common "click button → choose item from list" pattern. Items can be
 * regular item / separator / label entries.
 *
 *   <DropdownMenuCompose
 *     trigger={<Button>Actions ▾</Button>}
 *     items={[
 *       { label: 'Edit', onSelect: handleEdit, shortcut: '⌘E' },
 *       { label: 'Duplicate', onSelect: handleDup, shortcut: '⌘D' },
 *       { type: 'separator' },
 *       { label: 'Delete', onSelect: handleDel, tone: 'destructive' },
 *     ]}
 *   />
 * ──────────────────────────────────────────────────────────────── */
type DropdownMenuComposeItem =
  | {
      type?: 'item';
      label: React.ReactNode;
      onSelect?: () => void;
      shortcut?: React.ReactNode;
      disabled?: boolean;
      tone?: 'default' | 'destructive';
    }
  | { type: 'separator' }
  | { type: 'label'; label: React.ReactNode };

interface DropdownMenuComposeProps {
  trigger: React.ReactNode;
  items: DropdownMenuComposeItem[];
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: React.ComponentProps<typeof DropdownMenuContent>['side'];
  align?: React.ComponentProps<typeof DropdownMenuContent>['align'];
  className?: string;
}

function DropdownMenuCompose({
  trigger,
  items,
  open,
  onOpenChange,
  side,
  align,
  className,
}: DropdownMenuComposeProps) {
  return (
    <DropdownMenu open={open} onOpenChange={onOpenChange}>
      <DropdownMenuTrigger render={trigger as React.ReactElement} />
      <DropdownMenuContent side={side} align={align} className={className}>
        {items.map((item, i) => {
          if (item.type === 'separator') {
            return <DropdownMenuSeparator key={i} />;
          }
          if (item.type === 'label') {
            return <DropdownMenuLabel key={i}>{item.label}</DropdownMenuLabel>;
          }
          return (
            <DropdownMenuItem
              key={i}
              onClick={item.onSelect}
              disabled={item.disabled}
              data-tone={item.tone === 'destructive' ? 'destructive' : undefined}
              className={
                item.tone === 'destructive'
                  ? 'text-destructive data-[highlighted]:text-destructive'
                  : undefined
              }
            >
              {item.label}
              {item.shortcut ? (
                <DropdownMenuShortcut>{item.shortcut}</DropdownMenuShortcut>
              ) : null}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

// Dotted access — `<DropdownMenu.Compose ...>`. See dialog.tsx for pattern.
const DropdownMenuWithDot = Object.assign(DropdownMenu, {
  Compose: DropdownMenuCompose,
}) as typeof DropdownMenu & { Compose: typeof DropdownMenuCompose };

export {
  DropdownMenuWithDot as DropdownMenu,
  DropdownMenuPortal,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
  DropdownMenuCompose,
};
export type { DropdownMenuComposeProps, DropdownMenuComposeItem };
